settings.cellContentFunction:
var good = entity["Good Output"];
var reject = entity["Reject Output"];

var total = good + reject;
// return total
var goodPct = total > 0 ? ((good / total) * 100).toFixed(1) : 0.0;
return goodPct

dataKeys.postFuncBody:
switch (value) {
    case "running":
        return "🟢 Running";
    case "idle":
        return "🟡 Idle";
    case "downtime":
        return "🔴 Downtime";
    case "setup":
        return "🔵 Setup";
    default:
        return value;
}

totalValueColor.colorFunction:
var temperature = value;
if (typeof temperature !== undefined) {
  var percent = (temperature + 60)/120 * 100;
  return tinycolor.mix('blue', 'red', percent).toHexString();
}
return 'blue';

