settings.markdownCss:
.oee-card {
    background: #0f1724;
    border: 1px solid #243244;
    border-radius: 20px;
    padding: 20px;
    color: #fff;
    font-family: Inter, Roboto, sans-serif
}

.top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 18px
}

.title {
    font-size: 28px;
    font-weight: 700;
    line-height: 1
}

.sub {
    margin-top: 8px;
    color: #7d8a9d;
    font-size: 10px;
    letter-spacing: 1.4px
}

.badge {
    padding: 9px 12px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase
}

.badge.running {
    background: #163a2c;
    color: #4ade80
}

.badge.idle {
    background: #3b3315;
    color: #facc15
}

.badge.downtime {
    background: #3c1d20;
    color: #f87171
}

.grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    border: 1px solid #263548;
    border-radius: 16px;
    overflow: hidden
}

.cell {
    padding: 12px;
    border-right: 1px solid #263548;
    border-bottom: 1px solid #263548
}

.cell:nth-child(2n) {
    border-right: none
}

.cell:nth-child(n+5) {
    border-bottom: none
}

.lbl {
    font-size: 11px;
    color: #7b8798;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 8px
}

.val {
    font-size: 22px;
    font-weight: 600;
    color: #f8fafc
}

.bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 16px
}

.footlbl {
    font-size: 12px;
    color: #7b8798;
    letter-spacing: 1px;
    text-transform: uppercase
}

.plan {
    font-size: 38px;
    font-weight: 700;
    margin-top: 4px
}

.btn {
    padding: 12px 18px;
    border: 1px solid #334155;
    border-radius: 12px;
    background: #111b2c;
    color: #d1d5db;
    font-weight: 500
}

.count-card{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  background:#0F172A;
  border:1px solid #243244;
  border-radius:14px;
  overflow:hidden;
  font-family:Inter,Roboto,sans-serif;
}

.box{
  padding:14px 16px;
  border-right:1px solid #243244;
}

.box:last-child{
  border-right:none;
}

.label{
  font-size:10px;
  color:#7B8798;
  letter-spacing:1.8px;
  text-transform:uppercase;
  margin-bottom:6px;
}

.value{
  font-size:24px;
  font-weight:700;
  line-height:1;
}

.good .value{color:#34D399;}
.reject .value{color:#EF4444;}
.total .value{color:#F8FAFC;}

